import { createHash } from "node:crypto";

import { DeployError } from "./errors";
import type { StagedFile } from "./contract";

// =============================================================================
// Release-tag + commit conventions (ADR 0004 / platform.json)
// =============================================================================

/** CI's `COMMIT_RE` from publish_app.py: 12–40 lowercase hex. */
export const COMMIT_RE = /^[0-9a-f]{12,40}$/;

export const DEFAULT_RELEASE_TAG_CONVENTION = "apps-{app_slug}-{short_commit}";

/** CI uses `source_commit[:12]` as the short commit. */
export function shortCommit(commit: string): string {
  return commit.slice(0, 12);
}

export function assertValidCommit(commit: string): void {
  if (!COMMIT_RE.test(commit)) {
    throw new DeployError(
      "INVALID_COMMIT",
      `source commit must match ${COMMIT_RE} (12–40 lowercase hex), got ${JSON.stringify(commit)}`,
    );
  }
}

/**
 * Build the release tag from the platform's convention. Defaults to
 * `apps-<slug>-<commit[:12]>`. The convention MUST contain `{app_slug}` and
 * `{short_commit}` (CI enforces this on the descriptor).
 */
export function releaseTag(
  slug: string,
  commit: string,
  convention: string = DEFAULT_RELEASE_TAG_CONVENTION,
): string {
  assertValidCommit(commit);
  return convention
    .replaceAll("{app_slug}", slug)
    .replaceAll("{short_commit}", shortCommit(commit));
}

/**
 * Derive a deterministic 40-hex "commit" from staged file contents, for
 * browser uploads that have no git history. Stable across runs for identical
 * input: hashes the sorted `path\0sha256\0bytes` lines.
 */
export function deriveSourceCommit(files: StagedFile[]): string {
  const lines = files
    .map((f) => `${f.path}�${f.sha256}�${f.bytes}`)
    .sort();
  return createHash("sha256").update(lines.join("\n")).digest("hex").slice(0, 40);
}
